  if (AllBasePointersAreAllocas)
    return nullptr;

  // Check if any of the GEPs would produce undefined behavior when folded
  // into a single GEP. For example, if the base pointer is null, folding
  // would create a load from null which is undefined.
  for (Value *V : PN.incoming_values()) {
    GetElementPtrInst *GEP = dyn_cast<GetElementPtrInst>(V);
    if (!GEP)
      continue;

    // If any GEP has a null base pointer, we cannot safely fold
    if (isa<ConstantPointerNull>(GEP->getOperand(0)))
      return nullptr;
  }

  // Additional safety check: Before proceeding with the transformation,
  // verify that we're not going to create a GEP with a null base pointer
  // that could lead to undefined behavior.
  // Check if we're going to create a PHI for the base pointer and that
  // it could become null
  if (FixedOperands[0] == nullptr) {
